import math

# Helper function for LCM of two numbers
def lcm_two(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

# Function to compute LCM of a range of numbers [start, end] inclusive
def lcm_range(start, end):
    if start > end:
        return 1
    result = start
    for i in range(start + 1, end + 1):
        result = lcm_two(result, i)
    return result

N_values = [3, 4, 5]
K_values = [1, 2, 3]
results = {}

for n in N_values:
    results[n] = {}
    print(f"--- Results for n = {n} ---")
    for k in K_values:
        # x_k = lcm(k, k+1, ..., k+n-1)
        x_k = lcm_range(k, k + n - 1)

        # x_{k+1} = lcm(k+1, k+2, ..., k+n)
        x_k_plus_1 = lcm_range(k + 1, k + n)

        comparison = "x_{k+1} > x_k (Weakly Increasing)" if x_k_plus_1 > x_k else "x_{k+1} <= x_k (Not Weakly Increasing)"

        results[n][k] = {
            'x_k': x_k,
            'x_k_plus_1': x_k_plus_1,
            'comparison': comparison
        }

        print(f"k={k}: x_k = {x_k}")
        print(f"k={k}: x_{k+1} = {x_k_plus_1} -> {comparison}")

# Summary check
print("\n--- Summary ---")
for n, data in results.items():
    all_increasing = True
    for k in K_values:
        if not data[k]['comparison'].startswith("x_{k+1} > x_k"):
            all_increasing = False
            break
    print(f"n={n} appears eventually increasing based on k=1, 2, 3: {all_increasing}")

